from typing import List

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        g = [row[:] for row in grid]
        for r, c in hits:
            g[r][c] = 0

        parent = list(range(m * n + 1))
        size = [1] * (m * n + 1)
        TOP = m * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                size[rb] += size[ra]

        def idx(r, c):
            return r * n + c

        for r in range(m):
            for c in range(n):
                if g[r][c] == 1:
                    if r == 0:
                        union(idx(r, c), TOP)
                    if r > 0 and g[r-1][c] == 1:
                        union(idx(r, c), idx(r-1, c))
                    if c > 0 and g[r][c-1] == 1:
                        union(idx(r, c), idx(r, c-1))

        def top_size():
            return size[find(TOP)]

        result = [0] * len(hits)
        dirs = [(-1,0),(1,0),(0,-1),(0,1)]
        for i in range(len(hits)-1, -1, -1):
            r, c = hits[i]
            if grid[r][c] == 0:
                continue
            prev = top_size()
            g[r][c] = 1
            if r == 0:
                union(idx(r, c), TOP)
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0 <= nr < m and 0 <= nc < n and g[nr][nc] == 1:
                    union(idx(r, c), idx(nr, nc))
            cur = top_size()
            result[i] = max(0, cur - prev - 1)

        return result
