class Solution:
    def clumsy(self, n: int) -> int:
        stack = [n]
        n -= 1
        op = 0
        while n > 0:
            if op == 0:
                stack.append(stack.pop() * n)
            elif op == 1:
                v = stack.pop()
                stack.append(int(v / n))
            elif op == 2:
                stack.append(n)
            else:
                stack.append(-n)
            op = (op + 1) % 4
            n -= 1
        return sum(stack)
```

