class Solution:
    def canCross(self, stones: List[int]) -> bool:
        pos = set(stones)
        target = stones[-1]
        from functools import lru_cache
        import sys
        sys.setrecursionlimit(10000)

        memo = {}
        def dfs(cur, k):
            if cur == target:
                return True
            if (cur, k) in memo:
                return memo[(cur, k)]
            res = False
            for nk in (k - 1, k, k + 1):
                if nk > 0 and (cur + nk) in pos:
                    if dfs(cur + nk, nk):
                        res = True
                        break
            memo[(cur, k)] = res
            return res

        return dfs(0, 0)
```

