from math import gcd
from functools import lru_cache
from typing import List

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)

        @lru_cache(None)
        def dp(mask, op):
            if bin(mask).count('1') == m:
                return 0
            best = 0
            for i in range(m):
                if mask & (1 << i):
                    continue
                for j in range(i + 1, m):
                    if mask & (1 << j):
                        continue
                    nm = mask | (1 << i) | (1 << j)
                    best = max(best, op * gcd(nums[i], nums[j]) + dp(nm, op + 1))
            return best

        return dp(0, 1)
```

