from functools import lru_cache
from typing import List

class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        n = len(nums)

        @lru_cache(maxsize=None)
        def dp(i, mask):
            if i == n:
                return 0
            best = 0
            for slot in range(1, numSlots + 1):
                used = (mask >> (2 * (slot - 1))) & 3
                if used < 2:
                    new_mask = mask + (1 << (2 * (slot - 1)))
                    best = max(best, (nums[i] & slot) + dp(i + 1, new_mask))
            return best

        return dp(0, 0)
```

