from typing import List

class Solution:
    def maxEqualFreq(self, nums: List[int]) -> int:
        count = defaultdict(int)
        freq = defaultdict(int)
        ans = 0
        for i, x in enumerate(nums):
            c = count[x]
            if c > 0:
                freq[c] -= 1
                if freq[c] == 0:
                    del freq[c]
            count[x] += 1
            freq[count[x]] += 1

            n = i + 1
            valid = False
            if len(freq) == 1:
                k = next(iter(freq))
                if k == 1 or freq[k] == 1:
                    valid = True
            elif len(freq) == 2:
                keys = sorted(freq.keys())
                a, b = keys[0], keys[1]
                if a == 1 and freq[a] == 1:
                    valid = True
                elif b == a + 1 and freq[b] == 1:
                    valid = True
            if valid:
                ans = n
        return ans
