class Solution:
    def maxStudents(self, seats: List[List[str]]) -> int:
        m = len(seats)
        n = len(seats[0])
        valid = []
        for row in seats:
            mask = 0
            for j in range(n):
                if row[j] == '.':
                    mask |= (1 << j)
            valid.append(mask)

        def bits(x):
            return bin(x).count('1')

        prev = {0: 0}
        for i in range(m):
            avail = valid[i]
            cur = {}
            # enumerate subsets of avail with no two adjacent
            sub = avail
            subsets = []
            s = avail
            while True:
                if (s & (s << 1)) == 0:
                    subsets.append(s)
                if s == 0:
                    break
                s = (s - 1) & avail
            for s in subsets:
                best = -1
                for pmask, pval in prev.items():
                    if (s & (pmask << 1)) == 0 and (s & (pmask >> 1)) == 0:
                        if pval > best:
                            best = pval
                if best >= 0:
                    val = best + bits(s)
                    if s not in cur or cur[s] < val:
                        cur[s] = val
            prev = cur
        return max(prev.values()) if prev else 0
