class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):
            return -1

        def can(day):
            bouquets = 0
            adj = 0
            for b in bloomDay:
                if b <= day:
                    adj += 1
                    if adj == k:
                        bouquets += 1
                        adj = 0
                else:
                    adj = 0
            return bouquets >= m

        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
