class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        full = (1 << n) - 1

        @lru_cache(maxsize=None)
        def dp(mask, rem):
            if mask == full:
                return 0
            best = float('inf')
            for i in range(n):
                if not (mask & (1 << i)):
                    if tasks[i] <= rem:
                        best = min(best, dp(mask | (1 << i), rem - tasks[i]))
                    else:
                        best = min(best, 1 + dp(mask | (1 << i), sessionTime - tasks[i]))
            return best

        return 1 + dp(0, 0)
