                return 0
            rc = Counter(remaining)
            best = float('inf')
            for c in counters:
                if remaining[0] not in c:
                    continue
                new_rc = rc.copy()
                for ch, cnt in c.items():
                    if ch in new_rc:
                        new_rc[ch] -= cnt
                        if new_rc[ch] <= 0:
                            del new_rc[ch]
                new_str = ''.join(sorted(new_rc.elements()))
                res = dp(new_str)
                if res != -1:
                    best = min(best, 1 + res)
            return best if best != float('inf') else -1

        return dp(''.join(sorted(target)))
