class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        parent = list(range(4 * n * n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            parent[find(a)] = find(b)

        def idx(r, c, k):
            return (r * n + c) * 4 + k

        for r in range(n):
            for c in range(n):
                ch = grid[r][c]
                # k: 0 top, 1 right, 2 bottom, 3 left
                if ch == '/':
                    union(idx(r, c, 0), idx(r, c, 3))
                    union(idx(r, c, 1), idx(r, c, 2))
                elif ch == '\\':
                    union(idx(r, c, 0), idx(r, c, 1))
                    union(idx(r, c, 2), idx(r, c, 3))
                else:
                    union(idx(r, c, 0), idx(r, c, 1))
                    union(idx(r, c, 1), idx(r, c, 2))
                    union(idx(r, c, 2), idx(r, c, 3))
                # connect with right neighbor
                if c + 1 < n:
                    union(idx(r, c, 1), idx(r, c + 1, 3))
                # connect with bottom neighbor
                if r + 1 < n:
                    union(idx(r, c, 2), idx(r + 1, c, 0))

        return sum(1 for i in range(4 * n * n) if find(i) == i)
